const scores = $input.all().map(it => {
  const raw = String(it.json.output || '{}');
  const m = raw.match(/\{[\s\S]*\}/);
  try { return JSON.parse(m ? m[0] : raw); } catch (e) { return null; }
}).filter(Boolean);
const avg = k => scores.length ? Math.round(scores.reduce((a, s) => a + (Number(s[k]) || 0), 0) / scores.length * 10) / 10 : 0;
const joy = { ours: avg('ours'), sinjim: avg('sinjim'), mukhmukh: avg('mukhmukh') };
const crisis = joy.sinjim > joy.ours || joy.mukhmukh > joy.ours;
const prev = $('Spawn 9 Players').first().json;
return [{ json: {
  round: prev.round, joy, crisis,
  mode: crisis ? 'CODE_RED_JOY_CRISIS' : 'NORMAL',
  insights: scores.map(s => s.why_ours_loses).filter(Boolean),
  sessions: $('Collect Sessions').first().json.sessions
} }];

