const raw = String($input.first().json.output || '{}');
const m = raw.match(/\{[\s\S]*\}/);
let plan = {};
try { plan = JSON.parse(m ? m[0] : raw); } catch (e) { plan = {}; }
const meter = $('Joy Meter').first().json;
const init = $('Init Round State').first().json;
let state;
try { state = $('Restore State').last().json; } catch (e) { state = null; }
const base = state && state.round ? state : init;
return [{ json: {
  round: meter.round + 1,
  max_rounds: base.max_rounds,
  our_game: plan.updated_game_spec || base.our_game,
  last_plan: plan,
  history: (base.history || []).concat([{ round: meter.round, joy: meter.joy, changes: plan.changes || [] }])
} }];

const q = ($input.first().json.query) || {};
if (q.decision !== 'go') { return []; }
return [{ json: $('Prepare Next Round').last().json }];
